import {
  NEVER_CLIENT_REACHABLE,
  PRINCIPAL_KINDS,
  VISIBILITY_LEVELS,
  VISIBILITY_MEANING,
  canReachVisibility,
  isInternalPrincipal,
  principal,
  type Visibility,
} from "@/lib/access";
import styles from "./AccessMatrix.module.css";

function isNeverClientReachable(visibility: Visibility): boolean {
  return (NEVER_CLIENT_REACHABLE as readonly Visibility[]).includes(visibility);
}

/**
 * AccessMatrix — renders the authorization model **from the contract itself**
 * (Phase 3 §23).
 *
 * This is deliberate: the table is generated by calling `canReachVisibility()`
 * over the real `PRINCIPAL_KINDS` and `VISIBILITY_LEVELS` exports, not typed
 * out by hand. If someone ever widens a clearance ceiling, this page moves with
 * the contract and the change is visible — and the test suite fails.
 *
 * It renders no client data, no reports and no account state. It is a diagram
 * of the rules.
 */
export function AccessMatrix() {
  return (
    <div className={styles.wrap}>
      <div className={styles.scroll}>
        <table className={styles.table}>
          <caption className={styles.caption}>
            Reachability by principal kind. A tick means the class is reachable{" "}
            <em>in principle</em>; it never means automatic access — ownership, organisation or an
            unexpired grant is still required.
          </caption>
          <thead>
            <tr>
              <th scope="col" className={styles.rowHead}>
                Visibility class
              </th>
              {PRINCIPAL_KINDS.map((kind) => (
                <th key={kind} scope="col" className={styles.colHead}>
                  <span className={styles.kind}>{kind}</span>
                  <span className={styles.inside}>
                    {isInternalPrincipal(principal(kind, "x")) ? "inside" : "outside"}
                  </span>
                </th>
              ))}
            </tr>
          </thead>
          <tbody>
            {VISIBILITY_LEVELS.map((visibility) => (
              <tr key={visibility}>
                <th scope="row" className={styles.rowHead}>
                  <span className={styles.className}>{visibility}</span>
                  {isNeverClientReachable(visibility) ? (
                    <span className={styles.flag}>never client-reachable</span>
                  ) : null}
                </th>
                {PRINCIPAL_KINDS.map((kind) => {
                  const reachable = canReachVisibility(kind, visibility);
                  return (
                    <td key={kind} className={reachable ? styles.yes : styles.no}>
                      <span aria-hidden="true">{reachable ? "✓" : "—"}</span>
                      <span className="u-visually-hidden">
                        {reachable ? "reachable" : "not reachable"}
                      </span>
                    </td>
                  );
                })}
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      <dl className={styles.meanings}>
        {VISIBILITY_LEVELS.map((visibility) => (
          <div key={visibility} className={styles.meaning}>
            <dt className={styles.meaningTerm}>{visibility}</dt>
            <dd className={styles.meaningBody}>{VISIBILITY_MEANING[visibility]}</dd>
          </div>
        ))}
      </dl>
    </div>
  );
}
